	[KernelFunction, Description("(文法リファレンス)強弱")]
	public string Get5_36()
	{
		return """
┌────────────────────┐
│■強弱                          v ① ② │初期値 v100
└────────────────────┘
　①強弱値
	0～127の値。0で無音、127で最強となる。
	±符号付の数値を指定すると、現在の強弱値を基準にした相対変化となる。
	相対変化の結果が0～127の範囲を超える場合、限界値がセットされる。
	再度、本指定が行われるまで同一フィンガー内でこの値が維持される。
	v0の音も鍵盤表示されるが、MIDI出力やPDF出力の対象にはならない。

　②遅延音長（省略可能）
	上記強弱値に到達するまでの時間を、コロンに続けて音長表現で指定する。
	遅延は連続的に行われず、あくまでも発音時点での強弱変化である。
	音長表現の形式については“音符”の欄を参照のこと。
	ゼロ音長を指定すると遅延が起らず即座に作用する。
	本指定で与えた音長は、省略音長の対象にはならない。
	コロンのみの記述はできない。スタッカート指定“/”は使用できない。
	連符内に記述された遅延音長は、その連符比率でスケーリングされる。

""";
	}

	[KernelFunction, Description("(文法リファレンス)アクセント")]
	public string Get5_37()
	{
		return """
┌────────────────────┐
│■アクセント                       w ① │初期値 w+20
└────────────────────┘
　①アクセント値（省略可能）
	-127 ～ +127の値。
	強弱(v)への加算結果が0～127の範囲を超える場合は限界値で律則される。
	再度、本指定が行われるまで同一フィンガー内でこの値が維持される。
	省略した場合は、直前に指定したアクセント値が採用される。

　指定直後の音名に対してのみ、アクセント値分の強弱変化が起こる。
　和音やコードなどの直前に指定された場合、複数音に作用する。
　休符の直前にアクセントを記述することはできるが、無効である。

""";
	}

	[KernelFunction, Description("(文法リファレンス)音部記号")]
	public string Get5_38()
	{
		return """
┌────────────────────┐
│■音部記号                         ? ① │初期値 ?0
└────────────────────┘
　①音部値
	0 ～ 6 の値。ト音記号の音階を、指定された音部記号の音階に変換する。

	　　?0　ト音記号（高音部記号）
