	[KernelFunction, Description("(文法リファレンス)出音グルーヴ")]
	public string Get5_39()
	{
		return """
┌────────────────────┐
│■出音グルーヴ                     p ① │初期値 p0
└────────────────────┘
　①調整値
	+あるいは-に続く1～100の値で、音長に対する調整パーセントを与える。
	+の場合は音を早めに出し、-の場合は音を遅めに出す。
	p0の指定で出音調整を行わない指定となる。
	^あるいは~に続く音長記述での調整もできる。
	^の場合は音を早めに出し、~の場合は音を遅めに出す。
	音長の加算減算乗算による表現も可能である。
	音長記述の場合、連符内に記述しても連符音長比率の影響を受けない。

　記述した位置から作用を開始する。
　再度、本指定が行われるまで同一フィンガー内でこの値が維持される。

""";
	}

	[KernelFunction, Description("(文法リファレンス)止音グルーヴ")]
	public string Get5_40()
	{
		return """
┌────────────────────┐
│■止音グルーヴ                     q ① │初期値 q0
└────────────────────┘
　①調整値
	+あるいは-に続く1～100の値で、音長に対する調整パーセントを与える。
	+の場合は音を遅めに止め、-の場合は音を早めに止める。
	q0の指定で止音調整を行わない指定となる。
	^あるいは~に続く音長記述での調整もできる。
	^の場合は音を遅めに止め、~の場合は音を早めに止める。
	音長の加算減算乗算による表現も可能である。
	上記符号を付けず直接音長を指定した場合は、固定の音長指定となる。
	音長記述の場合、連符内に記述しても連符音長比率の影響を受けない。

　記述した位置から作用を開始する。
　再度、本指定が行われるまで同一フィンガー内でこの値が維持される。
　本指定は、スタッカート指定がなされている音符には作用しない。

""";
	}

	[KernelFunction, Description("(文法リファレンス)移調楽器")]
	public string Get5_41()
	{
		return """
┌────────────────────┐
│■移調楽器                      y ① ② │初期値 y/
└────────────────────┘
　①調号
	１～７個の + あるいは - の並び。
	+ が♯、- が♭を表し、その並びの数が♯あるいは♭の数に対応する。
	= はハ調を表現する。
	省略した場合は、全域属性の調性“\”の値が採用される。
	なお“x2”指定下において、音名“b”は調性の影響を受けない。
	また音名“h”は、フラット系の調性の影響を受けない。

　②移調値
	スラッシュに続けて 半音単位の -96 ～ 0 ～ +96 の値を指定する。
	記述された音程に対し、－で低音側、＋で高音側に移調する。
	12の倍数を指定することでオクターブ単位の上下となる。
	再度、本指定が行われるまで同一フィンガー内でこの値が維持される。
	省略した場合は、メンバー属性の移調“T”の値が採用される。

　なお、本指定はドラムメンバーに対しては機能しない。
　主な移調楽器と移調量の関係については、移調“T”の項を参考のこと。

""";
	}
}